entries[90531] = { ["name"] = "Plans: Ghost Iron Shield Spike", ["text"] = "Requires Blacksmithing (540)\nRequires The Klaxxi\n- Honored\nUse: Teaches you how to forge a Ghost Iron Shield Spike.\n\nGhost Iron Shield Spike\nBinds when equipped\nRequires Level 85\nUse: Attaches a ghost iron spike to your shield that sometimes deals 280 damage when you block with it.\n\nAttaching a ghost iron spike to your shield causes it to become soulbound.\nSell Price:\nRequires Ghost Iron Bar (12)" }
entries[90532] = { ["name"] = "Plans: Living Steel Weapon Chain", ["text"] = "Requires Blacksmithing (540)\nRequires The Klaxxi\n- Honored\nUse: Teaches you how to forge a Living Steel Weapon Chain.\n\nLiving Steel Weapon Chain\nBinds when equipped\nRequires Level 85\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 50% and increasing your expertise by 200 . Does not stack with other similar effects.\n\nAttaching the weapon chain causes the weapon to become soulbound.\nRequires Living Steel" }
